from __future__ import absolute_import

import logging as logger
from os import path

from .archive_content import ContentSnapshot
from .exceptions import NotExistPath
from .verify_snapshot import CheckSnapshot, SnapshotCrawler


class verify_snapshot(object):
    ROBOT_LIBRARY_SCOPE = "GLOBAL"

    @staticmethod
    def verify_snapshot(snapshot_path, paths_to_check):
        """
        :param snapshot_path: absolute or relative path to the snapshot zipFile
        :param paths_to_check: list of paths to verify.

        The path should contain also zip files in which files and directories were packed, example::

            ['RAC/racoam_snapshot.zip/RAC/RACLogFiles/BIM/RacOAM/racoam_runtime_bim.json']

        :return: InvalidSnapshotException if file from paths_to_check is not in snapshot or is empty
        """
        return SnapshotCrawler().verify_snapshot(snapshot_path, paths_to_check)

    @staticmethod
    def get_data_from_snapshot(path_to_snapshot):
        """
        Check the content of snapshot.zip file and return a dictionary.
        The key is the file name, the value is a list with full path and file size

        :param path_to_snapshot: Path to snapshot.zip archive

        :return: file_dict which is a dictionary which maps file names from the snapshot zip with their paths and sizes
         where the keys represent the file names (str) and the values represent their paths in the zip and their size:

            - for single occurrences: [path, size]
            - for duplicate filenames: [path1, size1, path2, size2, ...]
        """
        if path.exists(path_to_snapshot):
            logger.info("Path to zip file: {}".format(path_to_snapshot))
        else:
            raise NotExistPath(path_to_snapshot)
        content_snap = ContentSnapshot()
        file_dict = content_snap.content_zip(path_to_snapshot)
        if content_snap.broken_archives:
            logger.warn("There are {} broken archives in the snapshot.".format(len(content_snap.broken_archives)))
        return file_dict

    @staticmethod
    def validate_snapshot_using_custom_data(files_to_check, required_file_dict):
        """
        Check whether files defined in required_file_dict are in snapshot.zip file,
        Keyword get_data_from_snapshot should be used first.

        Structure required_file_dict specification file::

            {
                "mandatory_file": [
                    ".*log1.txt",
                    ".*file2.log"
                ],
                "not_mandatory_file": [
                    ".*not_mandatory_file3.log",
                    ".*file.txt"
                ]
            }

        Keyword fails in case at least one mandatory file wasn't found.
        Keyword fails when at least size of one file is equal zero.
        Table with the result is always attached to the report
        :param files_to_check: Dictionary returned by keyword get_data_from_snapshot
        :param required_file_dict: json file with specification

        :return: List containing Pattern, File location and Size of the file from zip
        """
        check_snap = CheckSnapshot(required_file_dict)
        check_snap.validate_snapshot(files_to_check)
        check_snap.final_verdict()
        return check_snap.create_table()

    @staticmethod
    def get_files_list_from_tar(tar_path):
        """
        Get the list of files from a TAR archive

        :param tar_path: Path to TAR file (str)

        :return: list of files (full path).
        """
        return ContentSnapshot.get_content_tar(tar_path)

    @staticmethod
    def validate_snapshot(files_to_check, json_spec_file):
        """
        Check whether files defined in the JSON specification file are in snapshot.zip file.
        Keyword get_data_from_snapshot should be used to obtain the dictionary first.

        Structure path_to_json_spec_file specification file::

            {
                "mandatory_file": [
                    ".*log1.txt",
                    ".*file2.log"
                ],
                "not_mandatory_file": [
                    ".*not_mandatory_file3.log",
                    ".*file.txt"
                ]
            }

        :param files_to_check: Dictionary returned by keyword get_data_from_snapshot
        :param path_to_json_spec_file: JSON file with specification

        :return: None
        """
        check_snap = CheckSnapshot(json_spec_file)
        check_snap.validate_snapshot(files_to_check)
        check_snap.final_verdict()
